<?php require_once __DIR__.'/../config/bootstrap.php';require_admin();$products=db()->query('SELECT p.*,c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC')->fetchAll();$orders=db()->query('SELECT o.*,u.name customer FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.created_at DESC')->fetchAll();$pageTitle='Painel de administração';require __DIR__.'/../includes/header.php';?><h1 class="admin-title h2 fw-bold mb-4">Painel de administração</h1><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h4">Produtos</h2><a class="btn btn-neon" href="product_form.php">+ Novo produto</a></div><div class="table-responsive"><table class="table table-striped align-middle"><thead><tr><th>Produto</th><th>Categoria</th><th>Preço</th><th>Estoque</th><th>Situação</th><th>Opções</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><?=e($p['name'])?></td><td><?=e($p['category']??'—')?></td><td><?=money($p['price'])?></td><td><?=$p['stock']?></td><td><?=$p['active']?'Ativo':'Inativo'?></td><td class="d-flex gap-2"><a class="btn btn-sm btn-outline-dark" href="product_form.php?id=<?=$p['id']?>">Editar</a><form method="post" action="product_delete.php"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="btn btn-sm btn-outline-danger" data-confirm="Desativar este produto?">Desativar</button></form></td></tr><?php endforeach;?></tbody></table></div><h2 class="h4 mt-5">Compras realizadas</h2><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Pedido</th><th>Cliente</th><th>Data</th><th>Pagamento</th><th>Total</th><th>Itens</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td>#<?=$o['id']?></td><td><?=e($o['customer'])?></td><td><?=e($o['created_at'])?></td><td><?=e($o['payment_method'])?></td><td><?=money($o['total'])?></td><td><a href="order.php?id=<?=$o['id']?>">Ver itens</a></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../includes/footer.php';?>
